const medicationClass=(id:string)=>medicationClasses.find(group=>group.ids.has(id))?.id??"outros";

const fmt=(n:number,digits=2)=>n.toLocaleString("pt-BR",{maximumFractionDigits:digits});

function Calculator({med}:{med:Medication}){
  const[regimenIndex,setRegimenIndex]=useState(0);const[weight,setWeight]=useState("20");const[presentationIndex,setPresentationIndex]=useState(0);
  const regimen=med.regimens[regimenIndex];const presentation=regimen.presentations[presentationIndex];const kg=Number(weight.replace(",","."));
  const weightBased=regimen.weightBased??regimen.age==="Pediatria";
  const calculated=weightBased&&regimen.doseMax>0&&Number.isFinite(kg)&&kg>0;
  let min=calculated?regimen.doseMin*kg:regimen.doseMin,max=calculated?regimen.doseMax*kg:regimen.doseMax;
  if(regimen.minDose){min=Math.max(min,regimen.minDose);max=Math.max(max,regimen.minDose)}
  if(regimen.maxDose){min=Math.min(min,regimen.maxDose);max=Math.min(max,regimen.maxDose)}
  const doseUnit=regimen.doseUnit??"mg";
  const rawValues=presentation?{min:min/presentation.concentration,max:max/presentation.concentration}:null;
  const values=rawValues&&regimen.perMinute?{min:rawValues.min*60,max:rawValues.max*60}:rawValues;
  const period=regimen.perMinute?"min":regimen.perHour?"h":regimen.perDay?"dia":"dose";
  const doseFormula=weightBased?`${fmt(regimen.doseMin)}${regimen.doseMax!==regimen.doseMin?`–${fmt(regimen.doseMax)}`:""} ${doseUnit}/kg/${period}`:`${fmt(regimen.doseMin)}${regimen.doseMax!==regimen.doseMin?`–${fmt(regimen.doseMax)}`:""} ${doseUnit}/${period}`;
  const converted=values&&presentation?`${fmt(values.min)}${values.max!==values.min?`–${fmt(values.max)}`:""} ${regimen.perMinute||regimen.perHour?"mL/h":regimen.perDay?`${presentation.unit}/dia`:`${presentation.unit}${(["gota","comprimido","sachê","jato"].includes(presentation.unit)&&values.max!==1)?"s":""}`}`:"";
  const prescription=presentation&&regimen.doseMax>0?`${med.name} — ${regimen.label}: ${fmt(min)}${max!==min?`–${fmt(max)}`:""} ${doseUnit}${regimen.perMinute?"/min":regimen.perHour?"/h":regimen.perDay?"/dia":""} (${converted}), ${regimen.interval}.${regimen.maxDay?` Máximo: ${regimen.maxDay}.`:""} Apresentação: ${presentation.label}.`:"";
  const setRegimen=(index:number)=>{setRegimenIndex(index);setPresentationIndex(0)};
  return <div className="medcalc">
    <div className="medcalc-controls"><label>Esquema<select value={regimenIndex} onChange={e=>setRegimen(Number(e.target.value))}>{med.regimens.map((r,i)=><option key={r.label} value={i}>{r.label}</option>)}</select></label>{weightBased&&regimen.doseMax>0&&<label>Peso (kg)<input inputMode="decimal" value={weight} onChange={e=>setWeight(e.target.value.replace(/[^0-9,.]/g,""))}/></label>}{regimen.presentations.length>0&&<label>Apresentação<select value={presentationIndex} onChange={e=>setPresentationIndex(Number(e.target.value))}>{regimen.presentations.map((p,i)=><option value={i} key={p.label}>{p.label}</option>)}</select></label>}</div>
    {regimen.doseMax>0?<div className="medresult"><small>{regimen.perMinute||regimen.perHour?"DOSE E VAZÃO CALCULADAS":"DOSE CALCULADA"}</small><strong>{fmt(min)}{max!==min?`–${fmt(max)}`:""} <span>{doseUnit}/{period}</span></strong>{values&&<b>{fmt(values.min)}{values.max!==values.min?`–${fmt(values.max)}`:""} {regimen.perMinute||regimen.perHour?"mL/h":regimen.perDay?`${presentation.unit}/dia`:`${presentation.unit}${(["gota","comprimido","sachê"].includes(presentation.unit))&&values.max!==1?"s":""}`}</b>}<p>{regimen.interval}{regimen.maxDay?` · máximo ${regimen.maxDay}`:""}</p>{presentation&&<em>{presentation.note}</em>}</div>:<div className="medresult text"><small>ESQUEMA POR FAIXA</small><strong>2 / 4 / 8 mg</strong><p>{regimen.note}</p></div>}
    {regimen.doseMax>0&&<div className="posology"><small>POSOLOGIA</small><dl><div><dt>Dose</dt><dd>{doseFormula}</dd></div><div><dt>Via</dt><dd>{regimen.label.split(" — ")[0]}</dd></div><div><dt>Frequência e duração</dt><dd>{regimen.interval}</dd></div>{(regimen.maxDay||regimen.maxDose)&&<div><dt>Dose máxima</dt><dd>{regimen.maxDay??`${fmt(regimen.maxDose!)} ${doseUnit}/dose`}</dd></div>}</dl>{prescription&&<button onClick={()=>navigator.clipboard?.writeText(prescription)}>Copiar prescrição pronta</button>}</div>}
    {regimen.note&&regimen.doseMax>0&&<p className="mednote">{regimen.note}</p>}
  </div>
}

export default function MedicationCatalog({initialQuery}:{initialQuery:string}){
  const[open,setOpen]=useState<string>("");const[openClass,setOpenClass]=useState<string>("");
  const query=initialQuery.trim().toLowerCase();
  const list=useMemo(()=>medications.filter(m=>!query||`${m.name} ${m.aliases.join(" ")} ${m.use} ${(clinicalIndications[m.id]??[]).join(" ")}`.toLowerCase().includes(query)),[query]);
  const groups=useMemo(()=>[...medicationClasses.map(group=>({...group,meds:medications.filter(m=>medicationClass(m.id)===group.id)})),{id:"outros",name:"Outros medicamentos",description:"Demais fichas clínicas do catálogo",ids:new Set<string>(),meds:medications.filter(m=>medicationClass(m.id)==="outros")}].filter(group=>group.meds.length),[]);
  const MedicationRow=({m}:{m:Medication})=><article className={`medication ${m.tone} ${open===m.id?"expanded":""}`}><button className="medication-summary" onClick={()=>setOpen(open===m.id?"":m.id)} aria-expanded={open===m.id}><div><small>{m.use}</small><h3>{m.name}</h3><p>{m.aliases.slice(0,3).join(" · ")}</p></div><span>{open===m.id?"−":"+"}</span></button>{open===m.id&&<div className="medication-body"><Calculator med={m}/><div className="meddetails"><div className="indications"><small>INDICAÇÕES CLÍNICAS</small>{(clinicalIndications[m.id]??[m.use]).map(i=><p key={i}>✓ {i}</p>)}</div><div><small>ALERTAS CLÍNICOS</small>{m.alerts.map(a=><p key={a}>⚠ {a}</p>)}</div><div><small>REFERÊNCIAS CLÍNICAS</small>{m.sources.map(s=><p key={s}>{s}</p>)}{m.referenceUrl&&<a href={m.referenceUrl} target="_blank" rel="noreferrer">Consultar referência ↗</a>}</div></div></div>}</article>;
  return <section className="medications" id="medicamentos"><div className="medications-head"><div><small>MEDICAMENTOS</small><h2>{query?"Resultados da busca":"Escolha a classe terapêutica."}</h2>{query&&<p>Dose, indicação e prescrição rápida para os medicamentos encontrados.</p>}</div><b>{query?`${list.length} fichas encontradas`:`${medications.length} medicamentos`}</b></div>{query?(list.length?<div className="medication-list search-results">{list.map(m=><MedicationRow m={m} key={m.id}/>)}</div>:<div className="empty"><b>Nenhum medicamento encontrado.</b><span>Busque pelo princípio ativo, nome comercial, doença ou indicação clínica.</span></div>):<div className="medication-classes">{groups.map(group=><section className={`medication-class ${openClass===group.id?"open":""}`} key={group.id}><button className="class-summary" onClick={()=>{setOpenClass(openClass===group.id?"":group.id);setOpen("")}} aria-expanded={openClass===group.id}><span className="class-icon">{group.name.slice(0,1)}</span><div><small>CLASSE TERAPÊUTICA</small><h3>{group.name}</h3><p>{group.description}</p></div><b>{group.meds.length}</b><i>{openClass===group.id?"−":"+"}</i></button>{openClass===group.id&&<div className="class-content"><div className="medication-list">{group.meds.map(m=><MedicationRow m={m} key={m.id}/>)}</div></div>}</section>)}</div>}</section>
}
